def is_balanced(s):
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')' and stack:
            stack.pop()
        else:
            return False
    return len(stack) == 0

def match_parens(lst):
    if any(char not in ['(', ')'] for string in lst for char in string):
        return 'No'

    left_count = sum(string.count('(') for string in lst)
    right_count = sum(string.count(')') for string in lst)

    if left_count != right_count:
        return 'No'

    all_perms = [''.join(perm) for perm in permutations(lst)]

    for perm in all_perms:
        if is_balanced(perm):
            return 'Yes'

    return 'No'

